import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.RemoveVolumeEntity{EntityRuntimeID: 7, Dimension: -1}
REMOVE = bytes.fromhex("0701")

PACKET = v2225.RemoveVolumeEntityPacket(entity_net_id=7, dimension_type=-1)


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_remove_volume_entity_is_packet_167(version):
    assert version.PACKETS[167] is version.RemoveVolumeEntityPacket


def test_remove_volume_entity_encodes_to_its_golden():
    assert bytes(PACKET) == REMOVE


def test_remove_volume_entity_decodes_from_its_golden():
    assert v2225.RemoveVolumeEntityPacket.from_bytes(REMOVE) == PACKET


def test_the_net_id_is_unsigned_and_the_dimension_zigzags():
    wire = bytes(v2225.RemoveVolumeEntityPacket(entity_net_id=300, dimension_type=2))
    assert len(wire) == 3
    assert wire[-1] == 4
